{
  "title": "Tính bán kính mặt cầu ngoại tiếp tứ diện OABC",
  "description": "Dựng tứ diện OABC với OA, OB, OC đôi một vuông góc. Tìm tâm mặt cầu ngoại tiếp và tính bán kính.",
  "memory_declarations": [
    {
      "name": "OABC",
      "type": "solid"
    },
    {
      "name": "R",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "label": "Gốc tọa độ O"
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [2, 0, 0],
      "source_fact_id": "oa_length",
      "label": "Điểm A trên trục Ox"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [0, 2, 0],
      "source_fact_id": "ob_length",
      "label": "Điểm B trên trục Oy"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 0, 2],
      "source_fact_id": "oc_length",
      "label": "Điểm C trên trục Oz"
    },
    {
      "kind": "construct_polygon",
      "target_var": "OAB_face",
      "vertices": ["O", "A", "B"],
      "label": "Mặt OAB"
    },
    {
      "kind": "construct_polygon",
      "target_var": "OAC_face",
      "vertices": ["O", "A", "C"],
      "label": "Mặt OAC"
    },
    {
      "kind": "construct_polygon",
      "target_var": "OBC_face",
      "vertices": ["O", "B", "C"],
      "label": "Mặt OBC"
    },
    {
      "kind": "construct_polygon",
      "target_var": "ABC_face",
      "vertices": ["A", "B", "C"],
      "label": "Mặt ABC"
    },
    {
      "kind": "construct_solid",
      "target_var": "OABC",
      "vertices": ["O", "A", "B", "C"],
      "faces": [
        ["O", "A", "B"],
        ["O", "A", "C"],
        ["O", "B", "C"],
        ["A", "B", "C"]
      ],
      "label": "Tứ diện OABC"
    },
    {
      "kind": "assign",
      "target_var": "vec_OB",
      "expr": {
        "kind": "vector_from_points",
        "from_point": "O",
        "to_point": "B"
      }
    },
    {
      "kind": "assign",
      "target_var": "vec_OC",
      "expr": {
        "kind": "vector_from_points",
        "from_point": "O",
        "to_point": "C"
      }
    },
    {
      "kind": "construct_point",
      "target_var": "P_xy",
      "expr": {
        "kind": "translate",
        "point": "A",
        "vector": "vec_OB"
      },
      "label": "Điểm (2,2,0) - đỉnh của hình chữ nhật OAPB"
    },
    {
      "kind": "construct_point",
      "target_var": "D_point",
      "expr": {
        "kind": "translate",
        "point": "P_xy",
        "vector": "vec_OC"
      },
      "label": "Điểm D(2,2,2) - đỉnh đối diện O của hình hộp chữ nhật"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "O",
        "b": "D_point"
      },
      "label": "Tâm mặt cầu ngoại tiếp M"
    },
    {
      "kind": "assign",
      "target_var": "R",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "M",
        "wrt": "O"
      },
      "label": "Bán kính mặt cầu ngoại tiếp"
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách tìm tâm và bán kính mặt cầu ngoại tiếp của một tứ diện đặc biệt có ba cạnh đôi một vuông góc tại một đỉnh, bằng cách sử dụng tính chất của hình hộp chữ nhật và tâm của nó."
}

